1	/**
2	 * spec-link-index — reads the org's spec/adr markdown and builds the
3	 * test-file → linked-lines index the `require-spec-link` rule matches against.
4	 *
5	 * The source of truth for a spec↔test link lives INSIDE the spec.md/adr `.md`
6	 * as an inline trailing parenthetical — `([validated by](path/to/test.ts#L42))`
7	 * — parsed by the canonical `linksForStatements` (reused here, not re-implemented).
8	 * Each test link contributes its `#Lline` to that test path's line set; a link
9	 * with no `#L` anchor marks the whole file linked.
10	 *
11	 * Split out of the rule so the pure index (buildLinkIndex) and the filesystem
12	 * walk (readSpecFiles) are testable without a RuleTester.
13	 */
14	import fs from "node:fs";
15	import path from "node:path";
16	import { linksForStatements, resolveLinkPath } from "./spec-parsers.mjs";
17	/** @typedef {{ lines: Set<number>, wholeFile: boolean }} LinkEntry */
18	export function toPosix(filePath) {
19	    return filePath.split(path.sep).join("/");
20	}
21	/** True when at least one of `dirs` exists under `root`. The rule uses this to
22	 * tell "no test is linked" from "the corpus was never found" (e.g. eslint run
23	 * from a subdirectory where `context.cwd` is not the repo root). */
24	export function corpusExists(root, dirs = ["specs", "adrs"]) {
25	    return dirs.some((dir) => fs.existsSync(path.join(root, dir)));
26	}
27	function testLinksOf(file) {
28	    return linksForStatements(file.content).flatMap(({ testLinks }) => testLinks.map((link) => ({ link, specPath: file.path })));
29	}
30	function entryFor(index, key) {
31	    const existing = index.get(key);
32	    if (existing) {
33	        return existing;
34	    }
35	    const created = { lines: new Set(), wholeFile: false };
36	    index.set(key, created);
37	    return created;
38	}
39	function recordLink(index, { link, specPath }) {
40	    const entry = entryFor(index, resolveLinkPath(link.path, specPath));
41	    if (link.line === null) {
42	        entry.wholeFile = true;
43	        return;
44	    }
45	    entry.lines.add(link.line);
46	}
47	/**
48	 * Fold every test link found across the given markdown files into a
49	 * `Map<repoRelTestPath, LinkEntry>`. Href paths are resolved to canonical
50	 * repo-root-relative form via the shared `resolveLinkPath` — the same resolver
51	 * the graph binder uses — so a `../`-relative href (relative to the spec's own
52	 * directory, as GitHub renders it) indexes under the test's repo-relative key
53	 * and matches, instead of a literal `../../apps/x.test.ts` miss.
54	 *
55	 * @param {Array<{ path: string, content: string }>} files
56	 * @returns {Map<string, LinkEntry>}
57	 */
58	export function buildLinkIndex(files) {
59	    const index = new Map();
60	    files.flatMap(testLinksOf).forEach((found) => recordLink(index, found));
61	    return index;
62	}
63	function readMarkdownUnder(root, base) {
64	    return fs
65	        .readdirSync(base, { recursive: true })
66	        .filter((entry) => entry.endsWith(".md"))
67	        .map((entry) => {
68	        const full = path.join(base, entry);
69	        return {
70	            path: toPosix(path.relative(root, full)),
71	            content: fs.readFileSync(full, "utf8"),
72	        };
73	    });
74	}
75	/**
76	 * Read every `*.md` under each of `dirs` (relative to `root`), returning
77	 * `{ path, content }` with a root-relative posix path. Absent dirs are skipped.
78	 *
79	 * @param {string} root
80	 * @param {string[]} [dirs]
81	 * @returns {Array<{ path: string, content: string }>}
82	 */
83	export function readSpecFiles(root, dirs = ["specs", "adrs"]) {
84	    return dirs
85	        .map((dir) => path.join(root, dir))
86	        .filter((base) => fs.existsSync(base))
87	        .flatMap((base) => readMarkdownUnder(root, base));
88	}
